def calc(expr: str) -> int | str:
    i = 0
    n = len(expr)

    def skip_spaces():
        nonlocal i
        while i < n and expr[i].isspace():
            i += 1

    def parse_primary():
        nonlocal i
        skip_spaces()

        if expr[i] == "(":
            i += 1
            value = parse_add()
            skip_spaces()
            i += 1  # ')'
            return value

        value = 0
        while i < n and expr[i].isdigit():
            value = value * 10 + (ord(expr[i]) - ord("0"))
            i += 1
        return value

    def parse_unary():
        nonlocal i
        skip_spaces()
        if i < n and expr[i] == "-":
            i += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        nonlocal i
        base = parse_primary()
        skip_spaces()

        if i < n and expr[i] == "^":
            i += 1
            exponent = parse_unary()
            if exponent < 0:
                raise ValueError
            return pow(base, exponent)

        return base

    def trunc_div(a, b):
        if b == 0:
            raise ZeroDivisionError
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def parse_mul():
        nonlocal i
        value = parse_unary()

        while True:
            skip_spaces()
            if i >= n or expr[i] not in "*/%":
                return value

            op = expr[i]
            i += 1
            right = parse_unary()

            if op == "*":
                value *= right
            elif op == "/":
                value = trunc_div(value, right)
            else:
                if right == 0:
                    raise ZeroDivisionError
                value -= right * trunc_div(value, right)

    def parse_add():
        nonlocal i
        value = parse_mul()

        while True:
            skip_spaces()
            if i >= n or expr[i] not in "+-":
                return value

            op = expr[i]
            i += 1
            right = parse_mul()
            value = value + right if op == "+" else value - right

    try:
        return parse_add()
    except (ValueError, ZeroDivisionError):
        return "error"
